import { getCategories, getPosts, getTags, getUsers } from "@/lib/api";
import { buildCategoryTree } from "@/lib/category-tree";
import CategoryTree from "@/components/CategoryTree";
import SearchBar from "@/components/SearchBar";
import PostCard from "@/components/PostCard";

interface HomePageProps {
  searchParams: { category?: string; tag?: string; q?: string };
}

export default async function HomePage({ searchParams }: HomePageProps) {
  const [categories, tags, users] = await Promise.all([
    getCategories(),
    getTags(),
    getUsers(),
  ]);

  const activeCategory = categories.find(
    (category) => category.slug === searchParams.category
  );
  const activeTag = tags.find((tag) => tag.name === searchParams.tag);

  const posts = await getPosts({
    categoryId: activeCategory?.id,
    tagId: activeTag?.id,
    query: searchParams.q,
  });

  const categoryTree = buildCategoryTree(categories);
  const categoryMap = new Map(categories.map((c) => [c.id, c.name]));
  const userMap = new Map(users.map((u) => [u.id, u.nickname]));

  const heading = searchParams.q
    ? `'${searchParams.q}' 검색 결과`
    : activeCategory
    ? activeCategory.name
    : "전체 글";

  return (
    <div className="home-layout">
      <aside className="home-sidebar">
        <SearchBar />
        <nav aria-label="카테고리">
          <CategoryTree nodes={categoryTree} activeSlug={searchParams.category} />
        </nav>
      </aside>
      <main className="home-main">
        <h1 className="home-heading">{heading}</h1>
        {posts.length === 0 ? (
          <p className="home-empty">조건에 맞는 글이 없습니다.</p>
        ) : (
          <div className="post-grid">
            {posts.map((post) => (
              <PostCard
                key={post.id}
                post={post}
                categoryName={categoryMap.get(post.categoryId) ?? ""}
                authorNickname={userMap.get(post.authorId) ?? ""}
              />
            ))}
          </div>
        )}
      </main>
    </div>
  );
}